KG42.register("rules-c6f68e5c057b84290b831b5c",{"id":"06-sdr_energy_sharing::v141-c-R001","paper":"06-sdr_energy_sharing","record":{"rule_id":"v141-c-R001","mechanism_id":"v141-a-M01","name":"Local market coordinator","process_stage":"coordination","market_meaning":"Updated requested quantities, represented by nonnegative net power, are submitted to the ESP after a scheduling step. Scope: Iterative energy-sharing scheduling with demand response among PV prosumers within one microgrid energy-sharing zone. Condition: NP_i^h ≥ 0 for the submitted time slot, corresponding to the total-buying-power branch. Updated offered quantities, represented by negative net power, are submitted to the ESP after a scheduling step. Scope: Iterative energy-sharing scheduling with demand response among PV prosumers within one microgrid energy-sharing zone. Condition: NP_i^h \u003c 0 for the submitted time slot, corresponding to the total-selling-power branch. The ESP may belong to the microgrid operator or an independent third-party company focused on energy sharing. Scope: Institutional organization of the ESP for the microgrid energy-sharing zone. The ESP is responsible for assuring power balance and payment balance in the energy-sharing zone. Scope: Zone-wide responsibilities of the ESP acting as the prosumers' agent. To preserve fairness, the ESP should not have an optimal objective with any tendency. Scope: Impartiality of the ESP's optimization objective in the energy-sharing zone. The ESP's profit should be limited in actual applications; no numerical profit cap is specified in this assertion. Scope: ESP profit in actual applications of the energy-sharing arrangement. The ESP may publish the fairness-index result to every prosumer. Scope: Daily fairness disclosure by the ESP to participating prosumers. Condition: After every day's operation.","independence_rationale":"Relations governed by the approved function coordination.local_operator under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.demand","bidding.supply","coordination.local_operator"],"E":[{"edge_id":"v141-c-R001-E001","source":"bidding.demand","target":"coordination.local_operator","type":"links","constraint_ids":["v141-c-R001-C001"],"evidence_ids":["v141-b-g01-e11","v141-b-g02-E-26"]},{"edge_id":"v141-c-R001-E002","source":"bidding.supply","target":"coordination.local_operator","type":"links","constraint_ids":["v141-c-R001-C002"],"evidence_ids":["v141-b-g01-e11","v141-b-g02-E-26"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"Daily fairness disclosure by the ESP to participating prosumers. | ESP profit in actual applications of the energy-sharing arrangement. | Impartiality of the ESP's optimization objective in the energy-sharing zone. | Institutional organization of the ESP for the microgrid energy-sharing zone. | Iterative energy-sharing scheduling with demand response among PV prosumers within one microgrid energy-sharing zone. | Zone-wide responsibilities of the ESP acting as the prosumers' agent.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e03","v141-b-g01-e05","v141-b-g01-e11","v141-b-g02-E-26","v141-b-g02-E-39","v141-b-g04-e34"]},"x":[{"variable_id":"v141-c-R001-x-NP_i_h","symbol":"NP_i^h","meaning":"Energy of net power of PV prosumer i in time slot h; nonnegative values are submitted as requested demand quantities, negative values as offered supply quantities.","kind":"operational","domain":"real-valued energy quantity (can be positive or negative)","unit":"kWh","indices":["i","h"],"evidence_ids":["v141-b-g01-e02","v141-b-g01-e11","v141-b-g02-E-03","v141-b-g02-E-26"]},{"variable_id":"v141-c-R001-x-TSP_h","symbol":"TSP^h","meaning":"Energy of total selling power in time slot h, aggregated from negative net powers.","kind":"operational","domain":"nonnegative real","unit":"kWh","indices":["h"],"evidence_ids":["v141-b-g01-e02","v141-b-g01-e11","v141-b-g02-E-03"]},{"variable_id":"v141-c-R001-x-TBP_h","symbol":"TBP^h","meaning":"Energy of total buying power in time slot h, aggregated from nonnegative net powers.","kind":"operational","domain":"nonnegative real","unit":"kWh","indices":["h"],"evidence_ids":["v141-b-g01-e02","v141-b-g01-e11","v141-b-g02-E-03"]}],"theta":[{"parameter_id":"v141-c-R001-theta-n","symbol":"n","meaning":"Total number of PV prosumers participant in the energy sharing zone.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g01-e02"]}],"phi":[{"constraint_id":"v141-c-R001-C001","kind":"procedural","role":"core","statement":"Updated requested quantities, represented by nonnegative net power, are submitted to the ESP after a scheduling step. Scope: Iterative energy-sharing scheduling with demand response among PV prosumers within one microgrid energy-sharing zone. Condition: NP_i^h ≥ 0 for the submitted time slot, corresponding to the total-buying-power branch.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand","coordination.local_operator"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e11","v141-b-g02-E-26","v141-b-g02-E-03","v141-b-g01-e02"]},{"constraint_id":"v141-c-R001-C002","kind":"procedural","role":"core","statement":"Updated offered quantities, represented by negative net power, are submitted to the ESP after a scheduling step. Scope: Iterative energy-sharing scheduling with demand response among PV prosumers within one microgrid energy-sharing zone. Condition: NP_i^h \u003c 0 for the submitted time slot, corresponding to the total-selling-power branch.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.supply","coordination.local_operator"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e11","v141-b-g02-E-26","v141-b-g02-E-03","v141-b-g01-e02"]},{"constraint_id":"v141-c-R001-C003","kind":"procedural","role":"core","statement":"The ESP may belong to the microgrid operator or an independent third-party company focused on energy sharing. Scope: Institutional organization of the ESP for the microgrid energy-sharing zone.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e03"]},{"constraint_id":"v141-c-R001-C004","kind":"procedural","role":"core","statement":"The ESP is responsible for assuring power balance and payment balance in the energy-sharing zone. Scope: Zone-wide responsibilities of the ESP acting as the prosumers' agent.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e03"]},{"constraint_id":"v141-c-R001-C005","kind":"procedural","role":"core","statement":"To preserve fairness, the ESP should not have an optimal objective with any tendency. Scope: Impartiality of the ESP's optimization objective in the energy-sharing zone.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e05"]},{"constraint_id":"v141-c-R001-C006","kind":"procedural","role":"core","statement":"The ESP's profit should be limited in actual applications; no numerical profit cap is specified in this assertion. Scope: ESP profit in actual applications of the energy-sharing arrangement.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-E-39"]},{"constraint_id":"v141-c-R001-C007","kind":"procedural","role":"core","statement":"The ESP may publish the fairness-index result to every prosumer. Scope: Daily fairness disclosure by the ESP to participating prosumers. Condition: After every day's operation.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g04-e34"]},{"constraint_id":"v141-c-R001-C008","kind":"mathematical","role":"supporting","statement":"Total buying power in time slot h is the sum of nonnegative net powers; equivalently, the demand-branch aggregation is TBP^h = sum_{i=1}^n NP_i^h with NP_i^h >= 0.","expression":"TBP^{h} = \\sum_{i=1}^{n} NP_i^{h}, \\quad NP_i^{h} \\geq 0","formalization_origin":"source","template_id":null,"members":["bidding.demand","coordination.local_operator"],"variable_refs":["v141-c-R001-x-NP_i_h","v141-c-R001-x-TBP_h"],"parameter_refs":["v141-c-R001-theta-n"],"evidence_ids":["v141-b-g01-e11","v141-b-g02-E-03","v141-b-g01-e02"]},{"constraint_id":"v141-c-R001-C009","kind":"mathematical","role":"supporting","statement":"Total selling power in time slot h is the negative sum of negative net powers; equivalently, the supply-branch aggregation is TSP^h = -sum_{i=1}^n NP_i^h with NP_i^h \u003c 0.","expression":"TSP^{h} = -\\sum_{i=1}^{n} NP_i^{h}, \\quad NP_i^{h} \u003c 0","formalization_origin":"source","template_id":null,"members":["bidding.supply","coordination.local_operator"],"variable_refs":["v141-c-R001-x-NP_i_h","v141-c-R001-x-TSP_h"],"parameter_refs":["v141-c-R001-theta-n"],"evidence_ids":["v141-b-g01-e11","v141-b-g02-E-03","v141-b-g01-e02"]}],"pi":[{"evidence_id":"v141-b-g01-e03","location":{"location_id":"src-0812c00672-p03-c2r1__v141-a-M01-participation","page":3,"printed_page":"3571","section":"II. ENERGY SHARING STRUCTURE OF PV PROSUMERS / B. Energy Sharing Structure","anchor_text":"NSE FOR MICROGRIDS OF PEER-TO-PEER PROSUMERS 3571 In order to facilitate the organization of energy ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"In order to facilitate the organization of energy sharing, a coordinator is required. Here, we introduce a new entity named Energy Sharing Provider (ESP). Generally, the ESP may belong to the microgrid operator or an independent third party company that focuses on the business mode of energy sharing, which provides energy sharing service for all participated PV prosumers. The ESP acts as an agent for prosumers and is responsible for assuring the power balance and the payment balance in the energy sharing zone. In this regard, the ESP is in charge of purchasing electricity from the utility grid, or from the PV prosumers with extra net power export, then selling electricity to other prosumers or the utility grid."},{"evidence_id":"v141-b-g01-e05","location":{"location_id":"src-0812c00672-p03-c2r2__v141-a-M01-participation","page":3,"printed_page":"3571","section":"II. ENERGY SHARING STRUCTURE OF PV PROSUMERS / B. Energy Sharing Structure","anchor_text":"charge of purchasing electricity from the utility grid, or from the PV prosumers with extra net powe","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"condition"},"source_text":"In the energy sharing zone, self-consumption of PV energy is still the first choice for PV prosumers. If PV energy can not satisfy the load demand, the PV prosumer would purchase energy agented by the ESP. If the demand of the PV prosumer is less than the production of PV source, the redundant PV power will be shared with other PV prosumers or sold to the utility grid via the ESP. In order to keep the fairness of energy sharing, the ESP should not have an optimal objective with any tendency, but it still needs to charge for service fee with the prosumers, as to cover the power losses and other possible expenditures."},{"evidence_id":"v141-b-g01-e11","location":{"location_id":"src-0812c00672-p04-c1r2__v141-a-M01-clearing","page":4,"printed_page":"3572","section":"III. ENERGY SHARING MODEL / A. Basic Model","anchor_text":"certain time slot based on the net power. Thus, the Total Selling Power (TSP) and Total Buying Power","equation_id":"(4),(5)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"As the loads and PV output of prosumers are different from each other, they would act on selling role or buying role at a certain time slot based on the net power. Thus, the Total Selling Power (TSP) and Total Buying Power (TBP) at time slot h can be calculated as: TSP^{h} = - \\sum_{i=1}^{n} NP_i^{h},   NP_i^{h} \u003c 0   (4) ; TBP^{h} = \\sum_{i=1}^{n} NP_i^{h},   NP_i^{h} \\geq 0   (5)"},{"evidence_id":"v141-b-g02-E-26","location":{"location_id":"src-0812c00672-p07-c1r4__v141-a-M01-coordination","page":7,"printed_page":null,"section":"IV.B Iterative Algorithm","anchor_text":"The interaction process for the energy sharing with DR is shown in Fig. 6. The overall process is im","equation_id":null,"figure_id":"Fig. 6","table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"unknown"},"source_text":"The interaction process for the energy sharing with DR is shown in Fig. 6. The overall process is implemented in a closed-loop iterative way. Optimal scheduling for each PV prosumer could be carried out according to the received internal price, considering the forecasting PV power, load consumption, and user's willingness. During the iterative optimization, the information exchange between the ESP and PV prosumers are listed in Table I.\nFor each step scheduling, PV prosumers' net power might be changed, and the new results will be sent to the ESP. Then the ESP recalculates and broadcasts the updated internal prices. After enough iterations, if all the PV prosumers can not adjust the scheduling anymore, the ﬁnal internal prices for PV energy sharing is decided."},{"evidence_id":"v141-b-g02-E-39","location":{"location_id":"src-0812c00672-p06-c1r4__v141-a-M01-coordination","page":6,"printed_page":null,"section":"D. Income Model of the ESP","anchor_text":"t β · NP ih · min TSP h, TBP h (21) Shi = TSP h + TBP h ⎨ Moreover, for the value of β, the service ","equation_id":"(20)-(21)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"condition"},"source_text":"Moreover, for the value of \\beta, the service fee should cover the losses of sharing power and other possible expenditures for organizing the sharing activities. In fact, the ESP is a virtual entity that cannot produce any PV energy, and thus the proﬁt should be limited for actual applications."},{"evidence_id":"v141-b-g04-e34","location":{"location_id":"src-0812c00672-p14-c1r3__v141-a-M01-participation","page":14,"printed_page":null,"section":null,"anchor_text":"s tota e e gy o oad s t g ( W ) o p osu e i . [ If all participants are shifted loads exactly propor","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-14.png","occurrence_role":"unknown"},"source_text":"If all participants are shifted loads exactly proportionally to their economic benefits, then K = 0. Large values of K indicate that some prosumers have been allocated more or less than their \"fair share\" of contributions. After every day's operation, the ESP can publish the result of fairness index to every prosumer. This result may affect the participating willingness of prosumers."},{"evidence_id":"v141-b-g01-e02","location":{"location_id":"src-0812c00672-p01-c2r2__v141-a-M01-pricing","page":1,"printed_page":"3569","section":"NOMENCLATURE","anchor_text":"ng S Income of the ESP in an operation day. re T P i Energy of original power consumption of PV pro-","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"NOMENCLATURE. B_m: Upper bound of PV energy feed in the utility grid. H: Total number of time slots in the operational time horizon. n: Total number of PV prosumers participant in the energy sharing zone. NP_i^h: Energy of net power of PV prosumer i in time slot h. NP_{i,ω}^h: Energy of net power of PV prosumer i in time slot h and scenario ω. P_i: PV energy of prosumer i in the operational time horizon. P_i^h: Produced PV energy of prosumer i in time slot h. Pr: Internal price set in the operational time horizon. Pr^h: Internal price in time slot h. Pr^{hω}: Internal price in time slot h and scenario ω. S: Income of the ESP in an operation day. TP_i: Energy of original power consumption of PV prosumer i in the operational time horizon. TP_i^h: Energy of the original power consumption of PV prosumer i in time slot h. TSP^h: Energy of total selling power in time slot h. TSP_ω^h: Energy of total selling power in time slot h and scenario ω. TBP^h: Energy of total buying power in time slot h. TBP_ω^h: Energy of total buying power in time slot h and scenario ω. TNP^h: Energy of total net power of the energy sharing zone in time slot h. SDR^h: SDR of the energy sharing zone in time slot h. SDR_ω^h: SDR of the energy sharing zone in time slot h and scenario ω. Pr_buy: Internal buying price of the energy sharing zone. Pr_sell: Internal selling price of the energy sharing zone. x_i: Adjusted power consumption profile of prosumer i in the operational time horizon. x_i^h: Adjusted power consumption of PV prosumer i in time slot h. inc_i: Equivalent cost of inconvenience of PV prosumer i. C_i^h(·): Cost function of PV prosumer i in time slot h. C_{i,ω}^h(·): Cost function of PV prosumer i in time slot h and scenario ω. α_i: Sensitivity coefficient of PV prosumer i. β: Percentage of service fee by shared energy. λ_buy: Unit price of buying energy from the utility grid. λ_sell: Unit price of selling energy to the utility grid. τ: Current time slot. δ_{i,ω}^h: Related error (%) of forecasted value of PV prosumer i in time slot h and scenario ω."},{"evidence_id":"v141-b-g02-E-03","location":{"location_id":"src-0812c00672-p04-c1r2__v141-a-M01-clearing","page":4,"printed_page":null,"section":null,"anchor_text":"certain time slot based on the net power. Thus, the Total Selling Power (TSP) and Total Buying Power","equation_id":"(4)-(5)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"Thus, the Total Selling Power (TSP) and Total Buying Power (TBP) at time slot h can be calculated as:\nTSP^{h} = -\\sum_{i=1}^{n} NP_{i}^{h}, \\quad NP_{i}^{h} \u003c 0 \\quad (4)\nTBP^{h} = \\sum_{i=1}^{n} NP_{i}^{h}, \\quad NP_{i}^{h} \\geq 0 \\quad (5)"}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-participation","v141-a-M01-pricing"],"extras":{"decision_anchor":"coordination.local_operator","graph_fact_supports":[[{"evidence_id":"v141-b-g02-E-26","quote":"For each step scheduling, PV prosumers' net power might be changed, and the new results will be sent to the ESP."},{"evidence_id":"v141-b-g01-e11","quote":"Thus, the Total Selling Power (TSP) and Total Buying Power (TBP) at time slot h can be calculated as: TSP^{h} = - \\sum_{i=1}^{n} NP_i^{h},   NP_i^{h} \u003c 0   (4) ; TBP^{h} = \\sum_{i=1}^{n} NP_i^{h},   NP_i^{h} \\geq 0   (5)"}],[{"evidence_id":"v141-b-g02-E-26","quote":"For each step scheduling, PV prosumers' net power might be changed, and the new results will be sent to the ESP."},{"evidence_id":"v141-b-g01-e11","quote":"Thus, the Total Selling Power (TSP) and Total Buying Power (TBP) at time slot h can be calculated as: TSP^{h} = - \\sum_{i=1}^{n} NP_i^{h},   NP_i^{h} \u003c 0   (4) ; TBP^{h} = \\sum_{i=1}^{n} NP_i^{h},   NP_i^{h} \\geq 0   (5)"}],[{"evidence_id":"v141-b-g01-e03","quote":"Generally, the ESP may belong to the microgrid operator or an independent third party company that focuses on the business mode of energy sharing"}],[{"evidence_id":"v141-b-g01-e03","quote":"The ESP acts as an agent for prosumers and is responsible for assuring the power balance and the payment balance in the energy sharing zone."}],[{"evidence_id":"v141-b-g01-e05","quote":"In order to keep the fairness of energy sharing, the ESP should not have an optimal objective with any tendency"}],[{"evidence_id":"v141-b-g02-E-39","quote":"In fact, the ESP is a virtual entity that cannot produce any PV energy, and thus the proﬁt should be limited for actual applications."}],[{"evidence_id":"v141-b-g04-e34","quote":"After every day's operation, the ESP can publish the result of fairness index to every prosumer."}]],"C2_formalization":{"graph_sha256":"5dbc0533f24e685955072243f2560e5fc37eb3ff20558bc9feb9d1acf95ff841","applicability":"formalized","reason":"The rule contains source-supported mathematical branch definitions for the coordination quantities TSP^h and TBP^h, formalized as C008 and C009 using the frozen demand/supply-to-local-operator edges. The remaining C001-C007 are procedural or institutional assertions without supplied formal expressions and remain not_formalized. B evidence remains unverified candidate support; no independent source review has been performed.","bindings":[{"object_id":"v141-c-R001-x-NP_i_h","node_ids":["bidding.demand","bidding.supply","coordination.local_operator"],"edge_ids":["v141-c-R001-E001","v141-c-R001-E002"],"rationale":"NP_i^h is the prosumer net-power quantity submitted to the local operator; nonnegative values route through the demand-to-operator edge E001, negative values through the supply-to-operator edge E002."},{"object_id":"v141-c-R001-x-TBP_h","node_ids":["bidding.demand","coordination.local_operator"],"edge_ids":["v141-c-R001-E001"],"rationale":"TBP^h aggregates the nonnegative NP_i^h values on the demand branch and is the demand quantity submitted to the local operator along E001."},{"object_id":"v141-c-R001-x-TSP_h","node_ids":["bidding.supply","coordination.local_operator"],"edge_ids":["v141-c-R001-E002"],"rationale":"TSP^h aggregates the magnitudes of negative NP_i^h values on the supply branch and is the supply quantity submitted to the local operator along E002."},{"object_id":"v141-c-R001-theta-n","node_ids":["coordination.local_operator"],"edge_ids":[],"rationale":"n sets the summation range over prosumers for the TSP^h and TBP^h aggregations computed by the local operator."},{"object_id":"v141-c-R001-C008","node_ids":["bidding.demand","coordination.local_operator"],"edge_ids":["v141-c-R001-E001"],"rationale":"C008 formalizes the demand-branch aggregation TBP^h = sum_{i=1}^n NP_i^h with NP_i^h >= 0, which corresponds to the demand-to-operator link E001."},{"object_id":"v141-c-R001-C009","node_ids":["bidding.supply","coordination.local_operator"],"edge_ids":["v141-c-R001-E002"],"rationale":"C009 formalizes the supply-branch aggregation TSP^h = -sum_{i=1}^n NP_i^h with NP_i^h \u003c 0, which corresponds to the supply-to-operator link E002."}],"revision_requests":[]},"C2_delivery":{"raw_sha256":"bce31e45f73db84c24935c27fa75d0daaf088dbc57daf1f1f72185242a1ac7c5","delivery_payload_sha256":"66d192a26a28bf43dd4565b3acf90303f8ec4e681fb096e85c353d02204cefd8","changes":[{"path":"theta.0.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."}],"scientific_fields_unchanged":true,"request_graph_sha256":"5dbc0533f24e685955072243f2560e5fc37eb3ff20558bc9feb9d1acf95ff841","scientific_correctness_verified":false}},"quarantined_references":[]}});
